package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// ProductSearchHandler handles product search requests
func ProductSearchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Basic validation - only allow alphanumeric categories
	for _, c := range category {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			http.Error(w, "invalid category", http.StatusBadRequest)
			return
		}
	}

	// Build query with ORDER BY - sort field is user-controlled
	orderClause := "name ASC"
	if sortField != "" {
		// Attempt to restrict sort fields
		allowed := []string{"name", "price", "rating", "created_at"}
		valid := false
		for _, a := range allowed {
			if strings.EqualFold(sortField, a) {
				valid = true
				break
			}
		}
		if !valid {
			// Fallback: still uses the field but wraps it (VULNERABLE)
			// Developer thought quoting would help but it doesn't for expressions
			orderClause = fmt.Sprintf("%s", sortField)
		} else {
			orderClause = sortField
		}
	}

	var query string
	if minPrice != "" {
		// minPrice is also injectable but less obvious
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price >= %s ORDER BY %s",
			category, minPrice, orderClause,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' ORDER BY %s",
			category, orderClause,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(
			`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, name, price, description,
		)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func main() {
	http.HandleFunc("/api/products/search", ProductSearchHandler)
	fmt.Println("Server starting on :8080")
	http.ListenAndServe(":8080", nil)
}
